// Sandbox controller: state, the recompute pipeline (cached unit maps -> scaled sum), the map
// canvas and its interactions. Panels, the cross-section, the pickers and the other screens live
// in their own modules and read the App instance.
import { combineMaps, type Combined, type ScaledMap } from "../engine/superpose";
import { roadPollutantFor } from "../engine/roads";
import { DOMAIN, EMIT_OF, LABEL, RAMP, rampBreaks, type FamilyKind } from "../data/catalogue";
import { cellColourIndex, isGas, scaleFloorUg, toDisplay } from "../data/units";
import type { AppData, Family, StandardRef, Tech } from "../data/model";
import { RoadMaps } from "../data/roadmaps";
import { FieldClient } from "../worker/client";
import { applyConfig, decodeConfig, encodeConfig, initialState, toConfig, type AppState, type PlacedSource, type SavedConfig } from "../state/state";
import type { EmitKey, Pollutant } from "../types";
import { fmt, segDist, roadName, rayInBox } from "./format";
import { MainEngine } from "./mainEngine";
import { Panels } from "./panels";
import { SectionView } from "./section";
import { renderAbout } from "./about";
import { LinearityTab } from "./linearityTab";

const $ = <T extends HTMLElement = HTMLElement>(id: string) => document.getElementById(id) as T;

export interface Perf { combineMs: number; paintMs: number; lastHourChangeMs: number | null; lastPlaceMs: number | null; samples: { what: string; ms: number }[] }

export class App {
  S: AppState;
  grid = { ...DOMAIN.grid };
  field: Combined | null = null;
  perf: Perf = { combineMs: 0, paintMs: 0, lastHourChangeMs: null, lastPlaceMs: null, samples: [] };
  fc: FieldClient;
  roadMaps: RoadMaps;
  mainEngine: MainEngine;
  panels: Panels;
  section: SectionView;
  linTab: LinearityTab;
  /** Last unit map used per source tag (kept while a new one is computed). */
  private tagMaps = new Map<number, { key: string; map: Float32Array }>();
  private pendingMaps = 0;
  private hourT0: number | null = null;
  private placeT0: number | null = null;
  private canvas = $<HTMLCanvasElement>("mapCanvas");
  private ctx = this.canvas.getContext("2d")!;
  private concImg = document.createElement("canvas");
  MW = 600; MH = 600;
  hoverCell: { i: number; j: number } | null = null;
  kbCursor: { i: number; j: number } | null = null;
  private drag: null | { kind: "handle"; h: "a" | "b" } | { kind: "source"; s: PlacedSource; moved: boolean } = null;
  private applyingHash = false;
  private roadAsked = new Set<string>();

  constructor(public D: AppData) {
    this.S = initialState(D.scenarios.find((s) => s.id === "convective_deep")?.id ?? D.scenarios[0].id);
    this.fc = new FieldClient(D.base, D.manifest);
    this.roadMaps = new RoadMaps(D.base, D.roadBaselines, this.grid);
    this.mainEngine = new MainEngine(D.base, D.manifest);
    this.concImg.width = this.grid.nx; this.concImg.height = this.grid.ny;
    this.panels = new Panels(this);
    this.section = new SectionView(this);
    this.linTab = new LinearityTab(this);
    (window as unknown as { __aq: App }).__aq = this;   // for inspection and measurements
  }

  // ------------------------------------------------------------------ derived values
  scenario() { return this.D.scenarioById[this.S.scenarioId]; }
  observedWd() { return this.scenario().wd_deg; }
  wd(): number { return this.S.settings.allowRotation && this.S.windFromDeg != null ? this.S.windFromDeg : this.observedWd(); }
  rotated(): boolean { return Math.abs(((this.wd() - this.observedWd() + 540) % 360) - 180) > 0.5; }
  emitKey(): EmitKey { return this.S.pollutant === "O3" ? "NOx" : EMIT_OF[this.S.pollutant]; }
  family(key: string): Family { return this.D.families.find((f) => f.key === key)!; }
  kind(s: PlacedSource): FamilyKind { return this.family(s.family).kind; }
  techList(s: PlacedSource, ek: EmitKey): Tech[] { return (this.D.controls.technologies[ek] || []).filter((t) => t.appliesTo.includes(s.family)); }
  techFor(s: PlacedSource, ek: EmitKey): Tech | null {
    const id = s.control[ek];
    if (!id || id === "none") return null;
    return this.techList(s, ek).find((t) => t.id === id) ?? null;
  }
  effRate(s: PlacedSource, ek: EmitKey = this.emitKey()): number {
    const t = this.techFor(s, ek);
    return (s.rates[ek] || 0) * (1 - (t ? t.efficiency : 0));
  }
  bgUg(pol: Pollutant = this.S.pollutant, scn = this.S.scenarioId): number {
    return this.D.backgrounds[scn]?.[pol]?.ug ?? 0;
  }
  roadPol(): string | null { return this.S.pollutant === "O3" ? null : roadPollutantFor(this.S.pollutant); }
  roadsActive(): boolean { return this.S.layers.roads && !this.rotated() && !!this.roadPol() && this.roadMaps.available && (this.S.roads.tier1 || this.S.roads.tier2); }
  tiersOn(): number[] { return [this.S.roads.tier1 ? 1 : 0, this.S.roads.tier2 ? 2 : 0].filter(Boolean); }

  /** Display conversion only: the engine stays in µg/m³; gases show in ppb unless µg/m³ is chosen. */
  conv(ug: number, pol: Pollutant = this.S.pollutant): { v: number; u: string } {
    return toDisplay(ug, pol, this.S.units, this.D.ugPerPpb);
  }
  /** Lower bound of the fixed colour scale for the current pollutant, in µg/m³. */
  scaleLoUg(pol: Pollutant = this.S.pollutant): number { return scaleFloorUg(pol, this.D.ugPerPpb); }
  showC(ug: number, pol?: Pollutant): string { const c = this.conv(ug, pol); return `${fmt(c.v)} ${c.u}`; }
  /** A standard's level in the display unit, exact when the standard is written in ppb or ppm (no rounding through µg/m³). */
  levelShown(st: StandardRef): string {
    if (this.S.units === "ppb" && isGas(st.pol)) {
      const u = st.levelUnits.toLowerCase();
      if (u === "ppb") return `${fmt(st.levelNum)} ppb`;
      if (u === "ppm") return `${fmt(st.levelNum * 1000)} ppb`;
    }
    return this.showC(st.ug, st.pol);
  }
  /** A standard's level in the display unit, with the unit it is written in when that differs (e.g. 35,000 ppb, written as 35 ppm). */
  levelText(st: StandardRef): string {
    const shown = this.levelShown(st);
    return shown === st.level ? shown : `${shown} (written as ${st.level} in the standard)`;
  }

  cellOf(x: number, y: number) {
    if (x < DOMAIN.xmin || x >= DOMAIN.xmax || y < DOMAIN.ymin || y >= DOMAIN.ymax) return null;
    return { i: Math.floor((x - DOMAIN.xmin) / DOMAIN.cellM), j: Math.floor((y - DOMAIN.ymin) / DOMAIN.cellM) };
  }
  cellCentre(c: { i: number; j: number }) { return { x: DOMAIN.xmin + DOMAIN.cellM * (c.i + 0.5), y: DOMAIN.ymin + DOMAIN.cellM * (c.j + 0.5) }; }
  standard() { return this.D.standards.find((s) => s.id === this.S.standardId) ?? null; }
  selected(): PlacedSource | undefined { return this.S.sources.find((q) => q.tag === this.S.selected); }

  // ------------------------------------------------------------------ pipeline
  pendingMapsCount() { return this.pendingMaps + (this.roadsPending() ? 1 : 0); }

  /** Request missing unit maps (async) and recombine with what is available now. */
  refresh(opts: { keepControls?: boolean } = {}) {
    if (this.S.pollutant !== "O3") this.ensureMaps();
    this.ensureRoads();
    this.combine();
    if (this.S.screen === "sandbox") {
      this.paint();
      this.drawMap();
      this.panels.renderAll(opts.keepControls);
      this.section.update(false);
    }
    this.syncHashLater();
  }

  private ensureMaps() {
    const scn = this.S.scenarioId, wd = this.wd();
    for (const s of this.S.sources) {
      const key = FieldClient.mapKey(s.sourceId, scn, s.x, s.y, wd);
      const cached = this.fc.cachedMap(key);
      if (cached) { this.tagMaps.set(s.tag, { key, map: cached }); this.failedMaps.delete(s.tag); continue; }
      const cur = this.tagMaps.get(s.tag);
      if (cur && cur.key === key) continue;
      if (this.failedMaps.get(s.tag) === key) continue;   // failed; waits for Retry
      if (this.inflight.get(s.tag) === key) continue;     // already requested; one count and one handler per request
      this.inflight.set(s.tag, key);
      this.pendingMaps++;
      this.setBusy();
      // Only the answer to the source's current request counts; an older one (the source moved,
      // or the hour changed and changed back) is ignored, success or failure.
      const current = () => this.S.sources.includes(s) && FieldClient.mapKey(s.sourceId, this.S.scenarioId, s.x, s.y, this.wd()) === key;
      this.fc.unitMap(s.sourceId, scn, s.x, s.y, wd, this.grid).then((map) => {
        this.pendingMaps--;
        if (this.inflight.get(s.tag) === key) this.inflight.delete(s.tag);
        if (current()) { this.failedMaps.delete(s.tag); this.tagMaps.set(s.tag, { key, map }); }
        this.afterAsync();
      }, (e) => {
        this.pendingMaps--;
        if (this.inflight.get(s.tag) === key) this.inflight.delete(s.tag);
        console.warn(e);
        if (current()) {
          this.failedMaps.set(s.tag, key); this.tagMaps.delete(s.tag);
          this.toast(`The data for S${s.tag} did not load (network problem). Its plume is missing from every value until it loads; use Retry in the Summary panel.`);
        }
        this.afterAsync();
      });
    }
    for (const tag of [...this.tagMaps.keys()]) if (!this.S.sources.some((q) => q.tag === tag)) this.tagMaps.delete(tag);
  }

  /** Sources whose field failed to load (tag to field key). */
  failedMaps = new Map<number, string>();
  /** Field key of the request in flight per source tag. */
  private inflight = new Map<number, string>();
  /** Road tiers (of the current hour and pollutant) whose map failed to load. */
  roadsFailed(): number[] {
    if (!this.roadsActive()) return [];
    return this.tiersOn().filter((t) => this.roadMaps.failed.has(RoadMaps.key(this.S.scenarioId, t, this.roadPol()!)));
  }
  /** Road maps of the current hour and pollutant still downloading. */
  roadsPending(): boolean {
    if (!this.roadsActive()) return false;
    return this.tiersOn().some((t) => { const k = RoadMaps.key(this.S.scenarioId, t, this.roadPol()!); return this.roadAsked.has(k) && !this.roadMaps.groundReady.has(k) && !this.roadMaps.failed.has(k); });
  }
  retryFailed() {
    this.failedMaps.clear();
    for (const k of this.roadMaps.failed) this.roadAsked.delete(k);
    this.roadMaps.failed.clear(); this.roadMaps.failedVert.clear();
    this.section.retryFailed(); this.panels.retryFailed();
    this.refresh();
  }

  private asyncRaf = 0;
  private afterAsync() {
    this.setBusy();
    if (this.pendingMaps === 0) {
      const now = performance.now();
      if (this.hourT0 != null) { this.perf.lastHourChangeMs = now - this.hourT0; this.perf.samples.push({ what: "hour change", ms: now - this.hourT0 }); this.hourT0 = null; }
      if (this.placeT0 != null) { this.perf.lastPlaceMs = now - this.placeT0; this.perf.samples.push({ what: "place or move", ms: now - this.placeT0 }); this.placeT0 = null; }
    }
    this.combine();   // keep the summed field current even when the page is not being drawn
    if (!this.asyncRaf) {
      const run = () => { this.asyncRaf = 0; this.refresh({ keepControls: true }); };
      // A short timer rather than requestAnimationFrame, which does not fire in a hidden tab.
      this.asyncRaf = window.setTimeout(run, 16);
    }
  }

  private ensureRoads() {
    const pol = this.roadPol();
    if (!pol || !this.roadMaps.available) return;
    for (const t of [1, 2]) {
      const k = RoadMaps.key(this.S.scenarioId, t, pol);
      if (!this.roadMaps.groundReady.has(k) && !this.roadAsked.has(k)) { this.roadAsked.add(k); this.roadMaps.loadGround(this.S.scenarioId, t, pol).then((m) => {
        if (!m && this.roadMaps.failed.has(k)) this.toast(`The tier ${t} road map did not load (network problem). Roads are missing from every value until it loads; use Retry in the Summary panel.`);
        this.afterAsync();
      }); }
    }
  }

  private setBusy() {
    const b = $("mapBusy");
    b.classList.toggle("hidden", this.pendingMaps === 0);
    b.textContent = this.pendingMaps ? `Computing ${this.pendingMaps} source map${this.pendingMaps > 1 ? "s" : ""}…` : "";
  }

  /** Scaled sum of the cached maps: the hot path for every slider. */
  combine() {
    const t0 = performance.now();
    const n = this.grid.nx * this.grid.ny;
    if (this.S.pollutant === "O3") { this.field = null; return; }
    const ek = this.emitKey();
    const srcs: ScaledMap[] = [];
    for (const s of this.S.sources) {
      const m = this.tagMaps.get(s.tag);
      if (m) srcs.push({ map: m.map, scale: this.effRate(s, ek) });
    }
    const roads: ScaledMap[] = [];
    if (this.roadsActive()) for (const t of this.tiersOn()) {
      const m = this.roadMaps.groundReady.get(RoadMaps.key(this.S.scenarioId, t, this.roadPol()!));
      if (m) roads.push({ map: m, scale: this.S.roads.trafficScale });
    }
    this.field = combineMaps(srcs, roads, this.bgUg(), n, this.field?.increment);
    this.perf.combineMs = performance.now() - t0;
  }

  /** Value parts at a display cell (for the summary and the tooltip). */
  partsAtCell(k: number): { bg: number; roads: { tier: number; v: number }[]; parts: { s: PlacedSource; v: number }[]; total: number } {
    const ek = this.emitKey();
    const parts = this.S.sources.map((s) => ({ s, v: (this.tagMaps.get(s.tag)?.map[k] ?? 0) * this.effRate(s, ek) }));
    const roads: { tier: number; v: number }[] = [];
    if (this.roadsActive()) for (const t of this.tiersOn()) {
      const m = this.roadMaps.groundReady.get(RoadMaps.key(this.S.scenarioId, t, this.roadPol()!));
      if (m) roads.push({ tier: t, v: m[k] * this.S.roads.trafficScale });
    }
    const bg = this.bgUg();
    return { bg, roads, parts, total: bg + parts.reduce((a, p) => a + p.v, 0) + roads.reduce((a, r) => a + r.v, 0) };
  }

  // ------------------------------------------------------------------ painting
  paint() {
    const t0 = performance.now();
    const cx = this.concImg.getContext("2d")!;
    const { nx, ny } = this.grid;
    const img = cx.createImageData(nx, ny);
    if (this.field && this.S.pollutant !== "O3") {
      const br = rampBreaks(this.scaleLoUg());
      const rgb = RAMP.map((h) => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)]);
      const inc = this.field.increment, bg = this.field.background, show = this.S.show;
      for (let j = 0; j < ny; j++) for (let i = 0; i < nx; i++) {
        // Coloured only where plumes and roads add at least the scale's lower bound (data/units.ts).
        const c = cellColourIndex(inc[j * nx + i], bg, show, br);
        if (c < 0) continue;
        const o = ((ny - 1 - j) * nx + i) * 4;
        img.data[o] = rgb[c][0]; img.data[o + 1] = rgb[c][1]; img.data[o + 2] = rgb[c][2]; img.data[o + 3] = 215;
      }
    }
    cx.putImageData(img, 0, 0);
    this.perf.paintMs = performance.now() - t0;
  }

  w2s(x: number, y: number): [number, number] {
    const k = this.MW / (DOMAIN.xmax - DOMAIN.xmin);
    return [(x - DOMAIN.xmin) * k, this.MH - (y - DOMAIN.ymin) * k];
  }
  s2w(px: number, py: number): [number, number] {
    const k = this.MW / (DOMAIN.xmax - DOMAIN.xmin);
    return [DOMAIN.xmin + px / k, DOMAIN.ymin + (this.MH - py) / k];
  }
  mPerPx() { return (DOMAIN.xmax - DOMAIN.xmin) / this.MW; }

  layout() {
    const wrap = $("mapWrap");
    const w = Math.max(200, Math.floor(wrap.clientWidth));
    this.MW = w; this.MH = w;
    const dpr = window.devicePixelRatio || 1;
    this.canvas.width = Math.round(w * dpr); this.canvas.height = Math.round(w * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    $("sandboxGrid").classList.toggle("expanded", this.S.expanded);
    $("sectionExpand").textContent = this.S.expanded ? "Collapse" : "Expand";
    this.drawMap();
    this.section.layout();
  }

  drawMap() {
    const c = this.ctx, MW = this.MW, MH = this.MH;
    c.clearRect(0, 0, MW, MH);
    c.fillStyle = "#f8f8f6"; c.fillRect(0, 0, MW, MH);
    // 5 km reference grid in place of a basemap
    c.strokeStyle = "#e2e2dc"; c.lineWidth = 1;
    for (let x = DOMAIN.xmin; x <= DOMAIN.xmax; x += 5000) { const [p] = this.w2s(x, DOMAIN.ymin); c.beginPath(); c.moveTo(p, 0); c.lineTo(p, MH); c.stroke(); }
    for (let y = DOMAIN.ymin; y <= DOMAIN.ymax; y += 5000) { const [, q] = this.w2s(DOMAIN.xmin, y); c.beginPath(); c.moveTo(0, q); c.lineTo(MW, q); c.stroke(); }
    if (this.S.layers.conc && this.field && this.S.pollutant !== "O3") {
      c.imageSmoothingEnabled = false;
      c.drawImage(this.concImg, 0, 0, MW, MH);
    }
    if (this.S.layers.limits) this.drawRoadBuffers();
    this.drawRoads();
    if (this.S.layers.grid || this.S.mode === "place") this.drawPlacementGrid();
    this.drawLandmarks();
    if (this.S.layers.limits) this.drawLimitShapes();
    if (this.S.layers.section && this.S.section) this.drawSectionLine();
    this.drawSources();
    if (this.S.probe) this.drawProbe();
    const hc = this.S.mode === "place" ? (this.hoverCell ?? this.kbCursor) : null;
    if (hc) {
      const cc = this.cellCentre(hc), [p, q] = this.w2s(cc.x - DOMAIN.cellM / 2, cc.y + DOMAIN.cellM / 2), sz = DOMAIN.cellM / this.mPerPx();
      c.strokeStyle = "#1f55a8"; c.lineWidth = 2; c.strokeRect(p, q, sz, sz);
    }
    if (this.S.mode === "select" && this.kbCursor && document.activeElement === this.canvas && !this.selected()) {
      const cc = this.cellCentre(this.kbCursor), [p, q] = this.w2s(cc.x - DOMAIN.cellM / 2, cc.y + DOMAIN.cellM / 2), sz = DOMAIN.cellM / this.mPerPx();
      c.setLineDash([3, 2]); c.strokeStyle = "#1f55a8"; c.lineWidth = 1.5; c.strokeRect(p, q, sz, sz); c.setLineDash([]);
    }
    this.drawCompass();
    c.strokeStyle = "#888"; c.lineWidth = 1; c.strokeRect(0.5, 0.5, MW - 1, MH - 1);
  }

  private roadPath(r: { line: [number, number][] }) {
    const c = this.ctx;
    c.beginPath();
    r.line.forEach(([x, y], k) => { const [p, q] = this.w2s(x, y); if (k) c.lineTo(p, q); else c.moveTo(p, q); });
  }
  private drawRoads() {
    const c = this.ctx, hidden = this.rotated();
    for (const r of this.D.roads.roads) {
      const on = (r.tier === 1 ? this.S.roads.tier1 : this.S.roads.tier2) && this.S.layers.roads && !hidden;
      this.roadPath(r);
      c.setLineDash(on ? [] : [3, 3]);
      c.strokeStyle = on ? "#4d4d48" : "#bdbdb7";
      c.lineWidth = r.tier === 1 ? 2 : 1.3;
      c.stroke();
    }
    c.setLineDash([]);
  }
  private hatch: CanvasPattern | null = null;
  private hatchPattern(): CanvasPattern | null {
    if (this.hatch) return this.hatch;
    const t = document.createElement("canvas"); t.width = 8; t.height = 8;
    const g = t.getContext("2d")!;
    g.fillStyle = "rgba(255,255,255,.3)"; g.fillRect(0, 0, 8, 8);
    g.strokeStyle = "rgba(163,0,28,.85)"; g.lineWidth = 1.4;
    g.beginPath(); g.moveTo(-2, 10); g.lineTo(10, -2); g.moveTo(-2, 2); g.lineTo(2, -2); g.moveTo(6, 10); g.lineTo(10, 6); g.stroke();
    this.hatch = this.ctx.createPattern(t, "repeat");
    return this.hatch;
  }
  /** Model-limits layer: road bands (50 m each side, at least 7 px wide) as a red hatch with a dark edge. */
  private drawRoadBuffers() {
    if (this.rotated()) return;
    const c = this.ctx, w = Math.max(7, 100 / this.mPerPx());
    c.lineCap = "round"; c.lineJoin = "round";
    const shown = this.D.roads.roads.filter((r) => (r.tier === 1 ? this.S.roads.tier1 : this.S.roads.tier2) && this.S.layers.roads);
    c.strokeStyle = "rgba(60,0,12,.8)"; c.lineWidth = w + 2;
    for (const r of shown) { this.roadPath(r); c.stroke(); }
    c.strokeStyle = this.hatchPattern() ?? "rgba(255,220,225,.9)"; c.lineWidth = w;
    for (const r of shown) { this.roadPath(r); c.stroke(); }
    c.lineCap = "butt";
  }
  private drawPlacementGrid() {
    const c = this.ctx;
    c.strokeStyle = "rgba(0,0,0,.09)"; c.lineWidth = 1;
    for (let x = DOMAIN.xmin; x <= DOMAIN.xmax; x += DOMAIN.cellM) { const [p] = this.w2s(x, 0); c.beginPath(); c.moveTo(p, 0); c.lineTo(p, this.MH); c.stroke(); }
    for (let y = DOMAIN.ymin; y <= DOMAIN.ymax; y += DOMAIN.cellM) { const [, q] = this.w2s(0, y); c.beginPath(); c.moveTo(0, q); c.lineTo(this.MW, q); c.stroke(); }
  }
  private drawLandmarks() {
    const c = this.ctx;
    c.font = "11px system-ui, sans-serif"; c.textBaseline = "middle"; c.textAlign = "left";
    for (const L of DOMAIN.landmarks) {
      const [p, q] = this.w2s(L.x, L.y);
      c.fillStyle = "#222";
      if (L.kind === "tri") { c.beginPath(); c.moveTo(p, q - 5); c.lineTo(p + 5, q + 4); c.lineTo(p - 5, q + 4); c.closePath(); c.fill(); }
      else { c.beginPath(); c.arc(p, q, 3.5, 0, 7); c.fill(); }
      c.lineWidth = 3; c.strokeStyle = "rgba(255,255,255,.85)"; c.strokeText(L.name, p + 7, q);
      c.fillStyle = "#222"; c.fillText(L.name, p + 7, q);
    }
  }
  private drawLimitShapes() {
    const c = this.ctx;
    for (const s of this.S.sources) {
      const [p, q] = this.w2s(s.x, s.y), k = this.kind(s);
      if (k === "stack") {
        // 250 m ring, at least 16 px so it stays clear of the stack symbol; white halo, hatched inside.
        const r = Math.max(16, 250 / this.mPerPx());
        c.save(); c.beginPath(); c.arc(p, q, r, 0, 7); c.clip();
        c.fillStyle = "rgba(255,255,255,.35)"; c.fillRect(p - r, q - r, 2 * r, 2 * r);
        c.strokeStyle = "rgba(163,0,28,.75)"; c.lineWidth = 1.2;
        for (let t = -2 * r; t < 2 * r; t += 4) { c.beginPath(); c.moveTo(p + t, q - r); c.lineTo(p + t + 2 * r, q + r); c.stroke(); }
        c.restore();
        c.beginPath(); c.arc(p, q, r, 0, 7); c.strokeStyle = "#fff"; c.lineWidth = 5; c.stroke();
        c.beginPath(); c.arc(p, q, r, 0, 7); c.strokeStyle = "#a3001c"; c.lineWidth = 2.2; c.stroke();
      }
      if (k === "area") {
        const half = 200 / this.mPerPx() / 2 + 3;
        c.save(); c.translate(p, q); c.rotate(((this.wd() + 180) % 360) * Math.PI / 180);
        c.strokeStyle = "#fff"; c.lineWidth = 4.5; c.strokeRect(-half, -half, 2 * half, 2 * half);
        c.setLineDash([4, 3]); c.strokeStyle = "#8a4b00"; c.lineWidth = 2; c.strokeRect(-half, -half, 2 * half, 2 * half);
        c.restore(); c.setLineDash([]);
      }
    }
  }
  private drawSources() {
    const c = this.ctx;
    c.font = "bold 11px system-ui, sans-serif"; c.textBaseline = "middle"; c.textAlign = "left";
    for (const s of this.S.sources) {
      const [p, q] = this.w2s(s.x, s.y), k = this.kind(s);
      c.lineWidth = 1.5; c.strokeStyle = "#111";
      if (s.family === "power_plant_stack") { c.fillStyle = "#333"; c.fillRect(p - 6, q - 6, 12, 12); c.strokeRect(p - 6, q - 6, 12, 12); }
      else if (k === "stack") { c.fillStyle = "#777"; c.beginPath(); c.arc(p, q, 6, 0, 7); c.fill(); c.stroke(); }
      else if (k === "area") {
        const half = Math.max(6, 200 / this.mPerPx() / 2);
        c.save(); c.translate(p, q); c.rotate(((this.wd() + 180) % 360) * Math.PI / 180);
        c.fillStyle = "rgba(255,255,255,.85)"; c.fillRect(-half, -half, 2 * half, 2 * half); c.strokeRect(-half, -half, 2 * half, 2 * half);
        c.beginPath(); for (let t = -half; t < half; t += 3) { c.moveTo(t, -half); c.lineTo(Math.min(half, t + 2 * half), half); } c.lineWidth = 0.8; c.stroke();
        c.restore();
      } else { c.fillStyle = "#ddd"; c.fillRect(p - 5, q - 5, 10, 10); c.strokeRect(p - 5, q - 5, 10, 10); }
      if (this.S.selected === s.tag) { c.strokeStyle = "#1f55a8"; c.lineWidth = 2.5; c.beginPath(); c.arc(p, q, 11, 0, 7); c.stroke(); }
      c.lineWidth = 3; c.strokeStyle = "#fff"; c.strokeText("S" + s.tag, p + 9, q - 9); c.fillStyle = "#111"; c.fillText("S" + s.tag, p + 9, q - 9);
    }
  }
  private drawSectionLine() {
    const c = this.ctx, { a, b } = this.S.section!;
    const [p1, q1] = this.w2s(a.x, a.y), [p2, q2] = this.w2s(b.x, b.y);
    c.setLineDash([6, 4]); c.strokeStyle = "#111"; c.lineWidth = 1.5;
    c.beginPath(); c.moveTo(p1, q1); c.lineTo(p2, q2); c.stroke(); c.setLineDash([]);
    for (const [p, q, t] of [[p1, q1, "A"], [p2, q2, "B"]] as [number, number, string][]) {
      c.fillStyle = "#fff"; c.strokeStyle = "#111"; c.lineWidth = 1.5;
      c.beginPath(); c.arc(p, q, 8, 0, 7); c.fill(); c.stroke();
      c.fillStyle = "#111"; c.font = "bold 10px system-ui"; c.textAlign = "center"; c.textBaseline = "middle"; c.fillText(t, p, q + 0.5); c.textAlign = "left";
    }
  }
  private drawProbe() {
    const c = this.ctx, [p, q] = this.w2s(this.S.probe!.x, this.S.probe!.y);
    c.strokeStyle = "#a3001c"; c.lineWidth = 2;
    c.beginPath(); c.moveTo(p - 9, q); c.lineTo(p + 9, q); c.moveTo(p, q - 9); c.lineTo(p, q + 9); c.stroke();
    c.beginPath(); c.arc(p, q, 5, 0, 7); c.stroke();
  }
  private drawCompass() {
    const c = this.ctx, x = this.MW - 44, y = 44;
    c.fillStyle = "rgba(255,255,255,.92)"; c.strokeStyle = "#999"; c.lineWidth = 1;
    c.beginPath(); c.arc(x, y, 30, 0, 7); c.fill(); c.stroke();
    c.fillStyle = "#444"; c.font = "10px system-ui"; c.textAlign = "center"; c.textBaseline = "alphabetic"; c.fillText("N", x, y - 20);
    const b = (this.wd() + 180) * Math.PI / 180, dx = Math.sin(b), dy = -Math.cos(b);
    c.strokeStyle = "#111"; c.lineWidth = 2.5;
    c.beginPath(); c.moveTo(x - dx * 18, y - dy * 18); c.lineTo(x + dx * 16, y + dy * 16); c.stroke();
    c.beginPath(); c.moveTo(x + dx * 18, y + dy * 18);
    c.lineTo(x + dx * 8 - dy * 6, y + dy * 8 + dx * 6); c.lineTo(x + dx * 8 + dy * 6, y + dy * 8 - dx * 6); c.closePath(); c.fillStyle = "#111"; c.fill();
    c.fillStyle = "#222"; c.font = "11px system-ui";
    const txt = `wind from ${Math.round(this.wd())}° · ${this.scenario().ws_m_s.toFixed(1)} m/s`;
    c.textAlign = "right"; c.lineWidth = 3; c.strokeStyle = "rgba(255,255,255,.9)"; c.strokeText(txt, this.MW - 6, y + 44); c.fillText(txt, this.MW - 6, y + 44);
    const km5 = 5000 / this.mPerPx();
    c.fillStyle = "#222"; c.fillRect(this.MW - 20 - km5, this.MH - 30, km5, 3); c.textAlign = "left"; c.fillText("5 km", this.MW - 20 - km5, this.MH - 36);
  }

  // ------------------------------------------------------------------ limits near a point
  limitFlagsAt(x: number, y: number, z = 0): [string, string][] {
    const flags: [string, string][] = [];
    for (const s of this.S.sources) {
      const d = Math.hypot(x - s.x, y - s.y), k = this.kind(s);
      if (k === "stack" && d < (z > 0 ? 250 : 100)) flags.push(["near_stack", `within ${z > 0 ? 250 : 100} m of S${s.tag}`]);   // ground values beyond 100 m were checked to about 5 %
      if (k === "area" && d < 200) flags.push(["area_inside", `on or next to area source S${s.tag}`]);
    }
    if (this.roadsActive()) {
      const r = this.nearestRoad(x, y, true);
      if (r && r.d < 50) flags.push(["near_road", `${Math.round(r.d)} m from ${roadName(r.road)}`]);
    }
    return flags;
  }
  nearestRoad(x: number, y: number, onlyShown: boolean) {
    let best = Infinity, road = null as null | AppData["roads"]["roads"][number];
    for (const r of this.D.roads.roads) {
      if (onlyShown && !(r.tier === 1 ? this.S.roads.tier1 : this.S.roads.tier2)) continue;
      for (let p = 1; p < r.line.length; p++) { const d = segDist(x, y, r.line[p - 1], r.line[p]); if (d < best) { best = d; road = r; } }
    }
    return road ? { d: best, road } : null;
  }

  // ------------------------------------------------------------------ actions
  setScenario(id: string) {
    if (id === this.S.scenarioId) return;
    this.S.scenarioId = id;
    if (!this.S.settings.allowRotation) this.S.windFromDeg = null;
    // A section line put along a plume follows that plume to the new hour's wind direction.
    const follow = this.S.sources.find((q) => q.tag === this.sectionFollows);
    if (follow) this.alignSection(follow);
    this.hourT0 = performance.now();
    this.refresh();
    this.prefetchHours();
  }
  setPollutant(p: Pollutant) {
    this.S.pollutant = p;
    const st = this.standard();
    if (!st || st.pol !== p) this.S.standardId = this.D.standards.find((s) => s.pol === p && s.sameAveraging)?.id ?? this.D.standards.find((s) => s.pol === p)?.id ?? "none";
    this.refresh();
  }
  placeSource(famKey: string, cell: { i: number; j: number }): PlacedSource | null {
    if (this.S.sources.length >= DOMAIN.maxSources) { this.flash(`At most ${DOMAIN.maxSources} sources can be placed (a limit that keeps the map responsive). Remove one first.`); return null; }
    if (this.S.sources.some((s) => s.cell.i === cell.i && s.cell.j === cell.j)) { this.flash("One source per 500 m cell. Choose another cell."); return null; }
    const f = this.family(famKey), cc = this.cellCentre(cell);
    const s: PlacedSource = { tag: this.S.nextTag++, family: famKey, sourceId: f.defaultOpt, cell, x: cc.x, y: cc.y, rates: { ...f.rates }, control: {} };
    this.S.sources.push(s); this.S.selected = s.tag;
    if (!this.S.section || this.S.sources.length === 1) this.alignSection(s);
    this.placeT0 = performance.now();
    this.announce(`Placed S${s.tag}, ${f.name}, in cell ${cell.i}, ${cell.j}.`);
    return s;
  }
  removeSource(s: PlacedSource) {
    this.S.sources = this.S.sources.filter((q) => q !== s);
    if (this.S.selected === s.tag) this.S.selected = null;
    this.announce(`Removed S${s.tag}.`);
    this.refresh();
  }
  moveSource(s: PlacedSource, cell: { i: number; j: number }): boolean {
    if (cell.i < 0 || cell.j < 0 || cell.i >= DOMAIN.ncell || cell.j >= DOMAIN.ncell) return false;
    if (this.S.sources.some((q) => q !== s && q.cell.i === cell.i && q.cell.j === cell.j)) return false;
    const cc = this.cellCentre(cell);
    if (cc.x === s.x && cc.y === s.y) return false;
    s.cell = cell; s.x = cc.x; s.y = cc.y;
    return true;
  }
  /** Source whose plume the section line was put along (until the user drags a line end). */
  sectionFollows: number | null = null;
  alignSection(s: PlacedSource) {
    this.sectionFollows = s.tag;
    const b = (this.wd() + 180) * Math.PI / 180, ux = Math.sin(b), uy = Math.cos(b);
    const up = rayInBox(s.x, s.y, -ux, -uy, 1500, DOMAIN), down = rayInBox(s.x, s.y, ux, uy, 10000, DOMAIN);
    this.S.section = {
      a: { x: s.x - up * ux, y: s.y - up * uy },
      b: { x: s.x + down * ux, y: s.y + down * uy },
      zTop: this.S.section?.zTop ?? 2500,
    };
  }
  setMode(m: AppState["mode"], fam: string | null = null) {
    this.S.mode = m;
    this.S.placeFamily = m === "place" ? fam : null;
    if (m === "place" && !this.kbCursor) this.kbCursor = this.cellOf((DOMAIN.xmin + DOMAIN.xmax) / 2, (DOMAIN.ymin + DOMAIN.ymax) / 2);
    this.canvas.style.cursor = m === "place" ? "copy" : m === "probe" ? "crosshair" : "default";
    this.panels.renderModeBits();
    this.drawMap();
  }

  /** Fetch the raw tiles of the placed source types for every hour, and prepare the current hour's palette. */
  prefetchHours() {
    const placed = [...new Set(this.S.sources.map((s) => s.sourceId))];
    const palette = this.D.families.flatMap((f) => f.options.map((o) => o.id));
    const idle = (cb: () => void) => ((window as unknown as { requestIdleCallback?: (f: () => void) => void }).requestIdleCallback ?? ((f: () => void) => setTimeout(f, 200)))(cb);
    idle(() => {
      this.fc.prefetch(this.S.scenarioId, palette, true).catch(() => {});
      for (const sc of this.D.scenarios) if (sc.id !== this.S.scenarioId) this.fc.prefetch(sc.id, placed, false).catch(() => {});
      const pol = this.roadPol();
      if (pol) for (const sc of this.D.scenarios) for (const t of [1, 2]) this.roadMaps.loadGround(sc.id, t, pol);
    });
  }

  // ------------------------------------------------------------------ messages
  private flashT = 0;
  flash(msg: string) {
    const el = $("mapMsg"); el.textContent = msg; el.classList.remove("hidden");
    clearTimeout(this.flashT);
    this.flashT = window.setTimeout(() => this.panels.renderMapMsg(), 2800);
  }
  private toastT = 0;
  toast(msg: string) {
    const el = $("toast"); el.textContent = msg; el.classList.remove("hidden");
    clearTimeout(this.toastT); this.toastT = window.setTimeout(() => el.classList.add("hidden"), 3500);
  }
  announce(msg: string) { $("mapStatus").textContent = msg; }

  // ------------------------------------------------------------------ screens
  setScreen(sc: AppState["screen"]) {
    this.S.screen = sc;
    document.querySelectorAll<HTMLElement>(".screen").forEach((el) => el.classList.toggle("active", el.id === "screen-" + sc));
    document.querySelectorAll<HTMLButtonElement>("#tabs button").forEach((b) => {
      b.classList.toggle("active", b.dataset.screen === sc);
      if (b.dataset.screen === sc) b.setAttribute("aria-current", "page"); else b.removeAttribute("aria-current");
    });
    if (sc === "sandbox") { this.layout(); this.refresh(); }
    if (sc === "linearity") this.linTab.show();
    if (sc === "about") renderAbout(this);
    window.scrollTo(0, 0);
  }
  setInstructor(on: boolean) {
    this.S.instructor = on;
    $("instrBadge").classList.toggle("hidden", !on);
    document.body.classList.toggle("instructor", on);
    this.linTab?.onConfigLoaded();   // remount so the linearity module sees the instructor flag
  }

  // ------------------------------------------------------------------ save and share
  async shareLink(): Promise<string> {
    const enc = await encodeConfig(toConfig(this.S, this.D.manifest.created));
    const url = new URL(location.href);
    url.hash = "cfg=" + enc;
    this.applyingHash = true;
    history.replaceState(null, "", url.href);
    this.applyingHash = false;
    return url.href;
  }
  private hashT = 0;
  /** Keep the address bar's link current (debounced), so reloading keeps the configuration. */
  syncHashLater() {
    if (!location.hash.startsWith("#cfg=")) return;
    clearTimeout(this.hashT);
    this.hashT = window.setTimeout(() => { this.shareLink().catch(() => {}); }, 600);
  }
  saveFile() {
    const cfg = toConfig(this.S, this.D.manifest.created);
    const blob = new Blob([JSON.stringify(cfg, null, 1)], { type: "application/json" });
    const a = document.createElement("a");
    const d = new Date(), p = (n: number) => String(n).padStart(2, "0");
    a.download = `aq-sandbox-config-${d.getFullYear()}${p(d.getMonth() + 1)}${p(d.getDate())}-${p(d.getHours())}${p(d.getMinutes())}.json`;
    a.href = URL.createObjectURL(blob);
    document.body.appendChild(a); a.click(); a.remove();
    setTimeout(() => URL.revokeObjectURL(a.href), 2000);
    return cfg;
  }
  loadConfig(cfg: SavedConfig, from: string) {
    const warn = applyConfig(this.S, cfg, {
      scenarioIds: this.D.scenarios.map((s) => s.id), familyOfSource: this.D.familyOfSource,
      cellOf: (x, y) => this.cellOf(x, y), cellCentre: (c) => this.cellCentre(c), maxSources: DOMAIN.maxSources,
      rateMax: Object.fromEntries(this.D.families.map((f) => [f.key, f.rateMax])),
      bounds: { xmin: DOMAIN.xmin, xmax: DOMAIN.xmax, ymin: DOMAIN.ymin, ymax: DOMAIN.ymax },
    });
    // Sources are renumbered from S1, so per-tag results from the previous configuration no longer apply.
    this.tagMaps.clear(); this.failedMaps.clear(); this.inflight.clear();
    this.hourT0 = performance.now();
    this.sectionFollows = null;
    $("configTitle").textContent = this.S.title; $("configTitle").classList.toggle("hidden", !this.S.title);
    this.linTab.onConfigLoaded();
    if (this.S.screen === "sandbox") { this.layout(); this.refresh(); } else this.setScreen(this.S.screen);
    this.prefetchHours();
    if (cfg.data_version && this.D.manifest.created && cfg.data_version !== this.D.manifest.created) warn.push("It was saved with an earlier version of the sandbox's data, so some values may differ from those recorded then.");
    this.toast(`Configuration loaded from ${from}: ${this.S.sources.length} source${this.S.sources.length === 1 ? "" : "s"}.${warn.length ? " " + warn.join(" ") : ""}`);
  }
  async loadFromHash(): Promise<boolean> {
    if (this.applyingHash) return false;
    const m = /#cfg=([^&]+)/.exec(location.hash);
    if (!m) return false;
    try { this.loadConfig(await decodeConfig(m[1]), "the link"); return true; } catch (e) { this.toast(`Could not read the configuration link: ${(e as Error).message}`); return false; }
  }

  // ------------------------------------------------------------------ map interactions
  bindMap() {
    const cv = this.canvas;
    const evPos = (e: PointerEvent): [number, number] => { const r = cv.getBoundingClientRect(); return [(e.clientX - r.left) * this.MW / r.width, (e.clientY - r.top) * this.MH / r.height]; };
    const hitSource = (px: number, py: number) => {
      for (let k = this.S.sources.length - 1; k >= 0; k--) { const s = this.S.sources[k], [p, q] = this.w2s(s.x, s.y); if (Math.hypot(px - p, py - q) < 11) return s; }
      return null;
    };
    const hitHandle = (px: number, py: number): "a" | "b" | null => {
      if (!this.S.layers.section || !this.S.section) return null;
      for (const h of ["a", "b"] as const) { const [p, q] = this.w2s(this.S.section[h].x, this.S.section[h].y); if (Math.hypot(px - p, py - q) < 12) return h; }
      return null;
    };
    cv.addEventListener("pointerdown", (e) => {
      const [px, py] = evPos(e), [X, Y] = this.s2w(px, py);
      cv.setPointerCapture(e.pointerId);
      const h = hitHandle(px, py);
      if (h) { this.drag = { kind: "handle", h }; this.sectionFollows = null; return; }
      if (this.S.mode === "place") {
        const cell = this.cellOf(X, Y);
        if (!cell || !this.S.placeFamily) return;
        if (this.placeSource(this.S.placeFamily, cell)) { $("mapTip").classList.add("hidden"); this.setMode("select"); this.refresh(); }
        return;
      }
      if (this.S.mode === "probe") { this.S.probe = { x: X, y: Y, z: this.S.probe?.z ?? 0 }; this.panels.renderProbe(); this.drawMap(); this.syncHashLater(); return; }
      const s = hitSource(px, py);
      if (s) { this.S.selected = s.tag; this.drag = { kind: "source", s, moved: false }; this.refresh(); return; }
    });
    cv.addEventListener("pointermove", (e) => {
      const [px, py] = evPos(e), [X, Y] = this.s2w(px, py), tip = $("mapTip");
      if (this.drag?.kind === "handle") {
        this.S.section![this.drag.h] = { x: Math.min(DOMAIN.xmax, Math.max(DOMAIN.xmin, X)), y: Math.min(DOMAIN.ymax, Math.max(DOMAIN.ymin, Y)) };
        this.drawMap(); this.section.update(true); return;
      }
      if (this.drag?.kind === "source") {
        const c = this.cellOf(X, Y);
        if (c && this.moveSource(this.drag.s, c)) { this.drag.moved = true; this.drawMap(); }
        return;
      }
      let txt = "";
      if (this.S.mode === "place") {
        const c = this.cellOf(X, Y);
        if (c && (!this.hoverCell || c.i !== this.hoverCell.i || c.j !== this.hoverCell.j)) { this.hoverCell = c; this.drawMap(); }
        if (c) txt = `Place ${this.family(this.S.placeFamily!).name.toLowerCase()} in cell (${c.i}, ${c.j})`;
      } else {
        const s = hitSource(px, py), h = hitHandle(px, py);
        if (h) txt = `Drag section end ${h.toUpperCase()}`;
        else if (s) txt = `S${s.tag} · ${this.family(s.family).name} · drag to move`;
        else if (this.field && this.S.pollutant !== "O3" && this.cellOf(X, Y)) {
          const i = Math.floor((X - this.grid.x0) / this.grid.d), j = Math.floor((Y - this.grid.y0) / this.grid.d);
          const k = j * this.grid.nx + i, v = this.field.increment[k] + (this.S.show === "total" ? this.field.background : 0);
          txt = `${this.showC(v)}${this.S.show === "total" ? "" : " increment"}${this.S.mode === "probe" ? " · click to probe" : ""}`;
          const r = this.nearestRoad(X, Y, false);
          if (r && r.d < 4 * this.mPerPx()) txt += ` · ${roadName(r.road)} (tier ${r.road.tier}${(r.road.tier === 1 ? this.S.roads.tier1 : this.S.roads.tier2) ? "" : ", off"})`;
        }
      }
      if (txt) { tip.textContent = txt; tip.style.left = (px * cv.getBoundingClientRect().width / this.MW) + "px"; tip.style.top = (py * cv.getBoundingClientRect().height / this.MH) + "px"; tip.classList.remove("hidden"); }
      else tip.classList.add("hidden");
    });
    cv.addEventListener("pointerup", () => {
      const d = this.drag; this.drag = null;
      if (d?.kind === "source" && d.moved) { this.placeT0 = performance.now(); this.announce(`Moved S${d.s.tag} to cell ${d.s.cell.i}, ${d.s.cell.j}.`); this.refresh(); }
      else if (d?.kind === "handle") { this.section.update(false); this.syncHashLater(); }
    });
    cv.addEventListener("pointerleave", () => { $("mapTip").classList.add("hidden"); if (this.hoverCell) { this.hoverCell = null; this.drawMap(); } });
    cv.addEventListener("focus", () => { if (!this.kbCursor) this.kbCursor = this.cellOf((DOMAIN.xmin + DOMAIN.xmax) / 2, (DOMAIN.ymin + DOMAIN.ymax) / 2); this.drawMap(); });
    cv.addEventListener("blur", () => this.drawMap());
    cv.addEventListener("keydown", (e) => this.onMapKey(e));
  }

  private onMapKey(e: KeyboardEvent) {
    const dir: Record<string, [number, number]> = { ArrowLeft: [-1, 0], ArrowRight: [1, 0], ArrowUp: [0, 1], ArrowDown: [0, -1] };
    const sel = this.selected();
    if (dir[e.key]) {
      e.preventDefault();
      const [di, dj] = dir[e.key], step = e.shiftKey ? 4 : 1;
      if (this.S.mode === "select" && sel) {
        if (this.moveSource(sel, { i: sel.cell.i + di * step, j: sel.cell.j + dj * step })) { this.placeT0 = performance.now(); this.announce(`S${sel.tag} moved to cell ${sel.cell.i}, ${sel.cell.j}.`); this.refresh({ keepControls: true }); }
        return;
      }
      const c = this.kbCursor ?? { i: 30, j: 30 };
      this.kbCursor = { i: Math.min(DOMAIN.ncell - 1, Math.max(0, c.i + di * step)), j: Math.min(DOMAIN.ncell - 1, Math.max(0, c.j + dj * step)) };
      const cc = this.cellCentre(this.kbCursor);
      if (this.S.mode === "probe") { this.S.probe = { x: cc.x, y: cc.y, z: this.S.probe?.z ?? 0 }; this.panels.renderProbe(); }
      this.announce(`Cell ${this.kbCursor.i}, ${this.kbCursor.j}.`);
      this.drawMap();
      return;
    }
    if (e.key === "Enter" && this.S.mode === "place" && this.kbCursor && this.S.placeFamily) {
      e.preventDefault();
      if (this.placeSource(this.S.placeFamily, this.kbCursor)) { this.setMode("select"); this.refresh(); }
    } else if ((e.key === "Delete" || e.key === "Backspace") && sel && this.S.mode === "select") {
      e.preventDefault(); this.removeSource(sel);
    }
  }
}

export { LABEL };
