// Number and text formatting helpers (no state).
export function fmt(v: number, n = 3): string {
  if (!isFinite(v)) return "—";
  const a = Math.abs(v);
  if (a === 0) return "0";
  if (a >= 1000) return Math.round(v).toLocaleString("en-US");
  if (a >= 10 && Math.abs(v - Math.round(v)) < 1e-6 * a) return String(Math.round(v));   // 75.0 -> 75
  if (a >= 100) return v.toFixed(0);
  if (a >= 10) return v.toFixed(1);
  if (a >= 1) return String(Number(v.toFixed(2)));                  // 5.00 -> 5, 1.69 stays
  return String(Number(v.toPrecision(Math.max(1, n - 1))));           // 0.50 -> 0.5
}

export function fmtUsd(v: number): string {
  if (!isFinite(v) || v === 0) return "$0";
  const a = Math.abs(v);
  if (a >= 1e9) return `$${(v / 1e9).toFixed(2)} B`;
  if (a >= 1e6) return `$${(v / 1e6).toFixed(a >= 1e8 ? 0 : a >= 1e7 ? 1 : 2)} M`;
  if (a >= 1e4) return `$${Math.round(v / 1e3).toLocaleString("en-US")}k`;
  return `$${Math.round(v).toLocaleString("en-US")}`;
}

export function esc(s: unknown): string {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]!);
}

export const pad2 = (n: number) => String(n).padStart(2, "0");

export function relCityHall(x: number, y: number, ch: { x: number; y: number }): string {
  const e = (x - ch.x) / 1000, n = (y - ch.y) / 1000;
  return `${Math.abs(e).toFixed(1)} km ${e >= 0 ? "E" : "W"}, ${Math.abs(n).toFixed(1)} km ${n >= 0 ? "N" : "S"} of City Hall`;
}

export function roadName(r: { ref: string | null; name: string }): string {
  return r.ref ? r.ref.replace(/^I /, "I-").replace(/^US /, "US ") : r.name;
}

export function segDist(x: number, y: number, a: [number, number], b: [number, number]): number {
  const dx = b[0] - a[0], dy = b[1] - a[1], L = dx * dx + dy * dy;
  const t = L ? Math.max(0, Math.min(1, ((x - a[0]) * dx + (y - a[1]) * dy) / L)) : 0;
  return Math.hypot(x - a[0] - t * dx, y - a[1] - t * dy);
}

/** Length of the ray from (x, y) along the unit vector (ux, uy), capped at maxLen, that stays inside the box.
 * Cutting the ray along its own direction keeps a section line on its bearing at the map edge. */
export function rayInBox(x: number, y: number, ux: number, uy: number, maxLen: number,
  box: { xmin: number; xmax: number; ymin: number; ymax: number }): number {
  let t = maxLen;
  if (ux > 1e-12) t = Math.min(t, (box.xmax - x) / ux);
  else if (ux < -1e-12) t = Math.min(t, (box.xmin - x) / ux);
  if (uy > 1e-12) t = Math.min(t, (box.ymax - y) / uy);
  else if (uy < -1e-12) t = Math.min(t, (box.ymin - y) / uy);
  return Math.max(0, t);
}
