// Main-thread side of the field workers: a small pool with source affinity (each source type is
// always routed to the same worker, so each field is loaded once), plus the per-source unit-map
// cache keyed WITHOUT rate or control (moving a rate slider never resamples).
import type { Manifest } from "../engine/manifest";
import type { DisplayGrid } from "../engine/superpose";
import { fieldKey, type Reply, type Request } from "./protocol";

type Pending = { resolve: (r: Reply) => void; reject: (e: Error) => void; worker: Worker };

export interface Timing { kind: string; ms: number; workerMs?: number; loadMs?: number; t: number }

export class FieldClient {
  private workers: Worker[] = [];
  private pending = new Map<number, Pending>();
  private nextId = 1;
  private respawns = 0;
  private mapCache = new Map<string, Float32Array>();
  private mapPending = new Map<string, Promise<Float32Array>>();
  readonly timings: Timing[] = [];
  readonly n: number;

  constructor(private base: string, private manifest: Manifest, nWorkers?: number) {
    const hc = typeof navigator !== "undefined" ? navigator.hardwareConcurrency || 4 : 4;
    this.n = Math.max(1, Math.min(nWorkers ?? hc - 1, 3));
    for (let i = 0; i < this.n; i++) this.workers.push(this.spawn());
  }

  private spawn(): Worker {
    const w = new Worker(new URL("./field.worker.ts", import.meta.url), { type: "module" });
    w.onmessage = (ev: MessageEvent<Reply>) => {
      const p = this.pending.get(ev.data.id);
      if (!p) return;
      this.pending.delete(ev.data.id);
      if (ev.data.ok) p.resolve(ev.data); else p.reject(new Error(ev.data.error));
    };
    // A worker that fails (module load error, out of memory) would leave its requests unanswered
    // for ever ("Computing…" stuck, the section frozen): reject them and start a fresh worker.
    const died = (why: string) => {
      for (const [id, p] of this.pending) if (p.worker === w) { this.pending.delete(id); p.reject(new Error(`field worker failed: ${why}`)); }
      const i = this.workers.indexOf(w);
      w.terminate();
      if (i >= 0 && this.respawns++ < 3) this.workers[i] = this.spawn();   // not for ever if it can never start
    };
    w.onerror = (ev) => { ev.preventDefault?.(); died(ev.message || "error"); };
    w.onmessageerror = () => died("unreadable message");
    w.postMessage({ type: "init", base: this.base, grids: this.manifest.grids, encoding: this.manifest.encoding, fields: this.manifest.fields } satisfies Request);
    return w;
  }

  private workerFor(sourceId: string): Worker {
    let h = 0;
    for (let i = 0; i < sourceId.length; i++) h = (h * 31 + sourceId.charCodeAt(i)) >>> 0;
    return this.workers[h % this.n];
  }

  private call(w: Worker, msg: Request, transfer: Transferable[] = []): Promise<Reply> {
    return new Promise((resolve, reject) => {
      this.pending.set((msg as { id: number }).id, { resolve, reject, worker: w });
      w.postMessage(msg, transfer);
    });
  }

  private note(t: Timing) { this.timings.push(t); if (this.timings.length > 400) this.timings.shift(); }

  static mapKey(sourceId: string, scenarioId: string, x: number, y: number, wd: number, z = 0) {
    return `${sourceId}|${scenarioId}|${x}|${y}|${wd.toFixed(3)}|${z}`;
  }

  cachedMap(key: string): Float32Array | undefined { return this.mapCache.get(key); }

  /** Unit map (per g/s) of one source on the display grid; cached by (source, hour, position, wind). */
  unitMap(sourceId: string, scenarioId: string, x: number, y: number, wd: number, grid: DisplayGrid, z = 0): Promise<Float32Array> {
    const key = FieldClient.mapKey(sourceId, scenarioId, x, y, wd, z);
    const hit = this.mapCache.get(key);
    if (hit) { this.mapCache.delete(key); this.mapCache.set(key, hit); return Promise.resolve(hit); }
    let p = this.mapPending.get(key);
    if (p) return p;
    const t0 = performance.now();
    p = this.call(this.workerFor(sourceId), { type: "unitMap", id: this.nextId++, sourceId, scenarioId, x, y, wd, grid, z }).then((r) => {
      this.note({ kind: "unitMap", ms: performance.now() - t0, workerMs: r.ms, loadMs: r.loadMs, t: Date.now() });
      this.mapCache.set(key, r.map!);
      this.mapPending.delete(key);
      while (this.mapCache.size > 48) this.mapCache.delete(this.mapCache.keys().next().value!);
      return r.map!;
    }, (e) => { this.mapPending.delete(key); throw e; });
    this.mapPending.set(key, p);
    return p;
  }

  /** Values per item (unit fields, per g/s) at the given points, sampled in the workers. */
  async points(scenarioId: string, wd: number, items: { sourceId: string; x: number; y: number; mirror?: boolean }[], xs: Float64Array, ys: Float64Array, zs: Float64Array): Promise<Float64Array[]> {
    const t0 = performance.now();
    const groups = new Map<Worker, number[]>();
    items.forEach((it, i) => { const w = this.workerFor(it.sourceId); if (!groups.has(w)) groups.set(w, []); groups.get(w)!.push(i); });
    const out: Float64Array[] = new Array(items.length);
    await Promise.all([...groups].map(async ([w, idx]) => {
      const r = await this.call(w, { type: "points", id: this.nextId++, scenarioId, wd, items: idx.map((i) => items[i]), xs, ys, zs });
      idx.forEach((i, k) => { out[i] = r.values![k]; });
    }));
    this.note({ kind: `points(${items.length}x${xs.length})`, ms: performance.now() - t0, t: Date.now() });
    return out;
  }

  /** Load fields ahead of use: `prepare` decodes them too (otherwise only the raw tile is fetched). */
  async prefetch(scenarioId: string, sourceIds: string[], prepare: boolean): Promise<void> {
    const groups = new Map<Worker, string[]>();
    for (const s of new Set(sourceIds)) { const w = this.workerFor(s); if (!groups.has(w)) groups.set(w, []); groups.get(w)!.push(fieldKey(s, scenarioId)); }
    await Promise.all([...groups].map(([w, keys]) => this.call(w, { type: "prefetch", id: this.nextId++, keys, prepare })));
  }
}
