// Field store: fetches tiles, keeps raw buffers (cheap) and a bounded LRU of prepared fields
// (about 5 MB each). Used inside the field workers and, for the linearity module's synchronous
// engine, on the main thread. No DOM access.
import { decodeTile, prepare, preparedBytes, type PreparedField } from "../engine/field";
import { dataFileUrl } from "../engine/manifest";
import type { FieldEntry, GridSpec } from "../engine/manifest";
import { fieldKey } from "./protocol";

export class FieldStore {
  private raw = new Map<string, ArrayBuffer>();
  private rawPending = new Map<string, Promise<ArrayBuffer>>();
  private prepared = new Map<string, PreparedField>();
  private entries = new Map<string, FieldEntry>();
  constructor(private base: string, private grids: Record<string, GridSpec>, private encoding: { name: string }, fields: FieldEntry[], private maxPreparedBytes = 64e6) {
    for (const f of fields) this.entries.set(fieldKey(f.source_id, f.scenario_id), f);
  }

  entry(key: string): FieldEntry {
    const e = this.entries.get(key);
    if (!e) throw new Error(`no field ${key} in the manifest`);
    return e;
  }
  has(key: string): boolean { return this.prepared.has(key); }

  /** Fetch the raw tile (cached). */
  fetchRaw(key: string): Promise<ArrayBuffer> {
    const r = this.raw.get(key);
    if (r) return Promise.resolve(r);
    let p = this.rawPending.get(key);
    if (!p) {
      const e = this.entry(key), url = dataFileUrl(this.base, e.file, e.sha256);
      p = fetch(url).then(async (res) => {
        if (!res.ok) throw new Error(`${url}: HTTP ${res.status}`);
        const b = await res.arrayBuffer();
        this.raw.set(key, b);
        this.rawPending.delete(key);
        return b;
      }, (e) => { this.rawPending.delete(key); throw e; });
      this.rawPending.set(key, p);
    }
    return p;
  }

  /** Fetch synchronously (main thread only; used when a synchronous caller needs a field that is not loaded). */
  fetchRawSync(key: string): ArrayBuffer {
    const r = this.raw.get(key);
    if (r) return r;
    const e = this.entry(key), url = dataFileUrl(this.base, e.file, e.sha256);
    const xhr = new XMLHttpRequest();
    xhr.open("GET", url, false);
    xhr.overrideMimeType("text/plain; charset=x-user-defined");
    xhr.send();
    if (xhr.status !== 200 && xhr.status !== 0) throw new Error(`${url}: HTTP ${xhr.status}`);
    const s = xhr.responseText, b = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) b[i] = s.charCodeAt(i) & 0xff;
    this.raw.set(key, b.buffer);
    return b.buffer;
  }

  /** Prepared field for sampling (decoded once, LRU-bounded). */
  async get(key: string): Promise<PreparedField> {
    const f = this.prepared.get(key);
    if (f) { this.touch(key, f); return f; }
    const buf = await this.fetchRaw(key);
    return this.prepareFrom(key, buf);
  }

  getSync(key: string): PreparedField {
    const f = this.prepared.get(key);
    if (f) { this.touch(key, f); return f; }
    return this.prepareFrom(key, this.fetchRawSync(key));
  }

  private prepareFrom(key: string, buf: ArrayBuffer): PreparedField {
    const existing = this.prepared.get(key);
    if (existing) return existing;
    const e = this.entry(key);
    const vals = decodeTile(buf, { encoding: this.encoding, grids: this.grids }, e);
    const f = prepare(vals, this.grids[e.frame], e);
    this.prepared.set(key, f);
    this.evict();
    return f;
  }

  private touch(key: string, f: PreparedField) { this.prepared.delete(key); this.prepared.set(key, f); }
  private evict() {
    let total = 0;
    for (const f of this.prepared.values()) total += preparedBytes(f);
    for (const [k, f] of this.prepared) {
      if (total <= this.maxPreparedBytes || this.prepared.size <= 2) break;
      this.prepared.delete(k); total -= preparedBytes(f);
    }
  }
}
