// "Linearity edge" tab: mounts Agent G's module (app/src/linearity/index.ts) through the contract's
// mountLinearity(root, ctx). A placeholder is shown while that module does not exist.
import type { LinearityContext, MountLinearity, Pollutant } from "../types";
import type { App } from "./app";
import { esc } from "./format";
import { PUBLIC_SITE } from "../config";

// Resolved at build time; an empty object when G's module is not present.
const modules = import.meta.glob<{ mountLinearity: MountLinearity }>("../linearity/index.ts");

export class LinearityTab {
  private unmount: (() => void) | null = null;
  private mounting = false;
  constructor(private app: App) {}

  get available(): boolean { return Object.keys(modules).length > 0; }

  context(): LinearityContext {
    const app = this.app, D = app.D;
    return {
      scenarioIds: D.scenarios.map((s) => s.id),
      getScenario: (id) => { const s = D.scenarioById[id]; if (!s) throw new Error(`unknown scenario ${id}`); return s; },
      getBackground: (id: string, p: Pollutant) => D.backgrounds[id]?.[p]?.ug ?? null,
      engine: {
        superpose: (pl, scn, xq, yq, zq) => app.mainEngine.superpose(pl, scn, xq, yq, zq),
        preload: (ids, scn) => app.mainEngine.preload(ids, scn),
      },
      record: (entry) => {
        app.S.linearity.push({ ...entry, t: typeof entry.t === "number" ? entry.t : Date.now() });
        app.syncHashLater();
      },
      records: app.S.linearity,
      instructor: PUBLIC_SITE ? false : app.S.instructor,   // no outcome notes in the public site
    };
  }

  async show() {
    const root = document.getElementById("linHost")!;
    if (this.unmount || this.mounting) return;
    const loader = Object.values(modules)[0];
    if (!loader) { this.placeholder(root); return; }
    this.mounting = true;
    try {
      const mod = await loader();
      root.innerHTML = "";
      this.unmount = mod.mountLinearity(root, this.context());
    } catch (e) {
      root.innerHTML = `<section class="panel"><h2>Linearity edge</h2><p class="flagline red"><span>The linearity module failed to start: ${esc((e as Error).message)}</span></p></section>`;
      console.error(e);
    } finally {
      this.mounting = false;
    }
  }

  /** A loaded configuration may carry linearity records: remount so the module sees them. */
  onConfigLoaded() {
    if (this.unmount) { try { this.unmount(); } catch (e) { console.warn(e); } this.unmount = null; }
    if (this.app.S.screen === "linearity") this.show();
  }

  private placeholder(root: HTMLElement) {
    root.innerHTML = `<section class="panel">
      <h2>Linearity edge: two sources, one secondary pollutant</h2>
      <p class="flagline red"><span><b>Linear engine applied to a secondary pollutant.</b> The sandbox adds single-source fields together, which assumes each source's contribution does not depend on the others. Ozone forms in reactions between NOx and VOC in sunlight, so this module tests that assumption.</span></p>
      <p>This module is being built (Agent G). It will ask for a prediction from the sandbox's adding rule first and then compare it with an ozone chemistry model for the same weather hours.</p>
      <p class="hint">Records made in this module are saved with the configuration (link or file).${this.app.S.linearity.length ? ` This configuration holds ${this.app.S.linearity.length} record(s).` : ""}</p>
    </section>`;
  }
}
