// Vertical cross-section along A-B: plume increment only (placed sources and, where the vertical
// road companion exists, roads), with the zi line and model notes. The per-source unit values are
// sampled in the workers once per geometry; rate and control changes only rescale them.
import { LABEL, LIMITS, RAMP, rampBreaks } from "../data/catalogue";
import { RoadMaps, verticalValue } from "../data/roadmaps";
import type { App } from "./app";
import { esc } from "./format";

const $ = (id: string) => document.getElementById(id)!;

interface SecData { key: string; nx: number; nz: number; zTop: number; zs: Float64Array; xs: Float64Array; ys: Float64Array; units: Map<number, Float64Array>; coarse: boolean }

export class SectionView {
  private cv = document.getElementById("sectionCanvas") as HTMLCanvasElement;
  private ctx = this.cv.getContext("2d")!;
  private W = 600; private H = 240;
  private data: SecData | null = null;
  private seq = 0;
  private inflight = false;
  private queued: boolean | null = null;
  lastMs = 0;
  /** What the last draw put on the canvas, for the hover readout. */
  private shown: { inc: Float64Array; nx: number; nz: number; zTop: number; l: number; t: number; pw: number; ph: number; len: number } | null = null;

  constructor(private app: App) {
    this.cv.addEventListener("pointermove", (e) => this.readout(e));
    this.cv.addEventListener("pointerleave", () => this.readout(null));
  }

  /** Hover readout: value under the pointer, distance along the line and the column's peak height. */
  private readout(e: PointerEvent | null) {
    const out = document.getElementById("sectionReadout"), sh = this.shown, app = this.app, sec = app.S.section;
    if (!out) return;
    const idle = "Hover over the section to read the value, the distance downwind of the source and the height of the highest value in that column.";
    if (!e || !sh || !sec) { out.textContent = idle; return; }
    const r = this.cv.getBoundingClientRect(), px = e.clientX - r.left, py = e.clientY - r.top;
    const fx = (px - sh.l) / sh.pw, fz = 1 - (py - sh.t) / sh.ph;
    if (fx < 0 || fx > 1 || fz < 0 || fz > 1) { out.textContent = idle; return; }
    const i = Math.min(sh.nx - 1, Math.floor(fx * sh.nx)), k = Math.min(sh.nz - 1, Math.floor(fz * sh.nz));
    let kmax = 0, vmax = 0;
    for (let q = 0; q < sh.nz; q++) { const v = sh.inc[q * sh.nx + i]; if (v > vmax) { vmax = v; kmax = q; } }
    const dA = fx * sh.len, z = Math.round(fz * sh.zTop);
    // Distance downwind of the source the line follows, else of the first source lying on the line.
    const on = app.S.sources.map((s) => {
      const t = ((s.x - sec.a.x) * (sec.b.x - sec.a.x) + (s.y - sec.a.y) * (sec.b.y - sec.a.y)) / (sh.len * sh.len);
      const off = Math.hypot(s.x - (sec.a.x + t * (sec.b.x - sec.a.x)), s.y - (sec.a.y + t * (sec.b.y - sec.a.y)));
      return { s, t, off };
    }).filter((q) => q.t >= 0 && q.t <= 1 && q.off <= 250);
    const ref = on.find((q) => q.s.tag === app.sectionFollows) ?? on[0];
    const rel = ref ? `; ${(Math.abs(dA - ref.t * sh.len) / 1000).toFixed(2)} km ${dA >= ref.t * sh.len ? "downwind" : "upwind"} of S${ref.s.tag}` : "";
    const v = sh.inc[k * sh.nx + i];
    out.textContent = `${(dA / 1000).toFixed(2)} km from A${rel}, ${z} m: ${v > 0 ? app.showC(v) : "0"}. Highest in this column: ${vmax > 0 ? `${app.showC(vmax)} at about ${Math.round(((kmax + 0.5) / sh.nz) * sh.zTop)} m` : "none"}.`;
  }

  layout() {
    const w = Math.max(280, Math.floor(this.cv.clientWidth || 600)), h = Math.max(160, Math.floor(this.cv.clientHeight || 240));
    this.W = w; this.H = h;
    const dpr = window.devicePixelRatio || 1;
    this.cv.width = Math.round(w * dpr); this.cv.height = Math.round(h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.draw();
  }

  private geomKey(coarse: boolean) {
    const S = this.app.S, sec = S.section;
    if (!sec) return "";
    return JSON.stringify([S.scenarioId, this.app.wd().toFixed(3), sec.a, sec.b, sec.zTop, coarse, S.sources.map((s) => [s.tag, s.sourceId, s.x, s.y])]);
  }

  /** Recompute (async) when the geometry changed; otherwise redraw with the current rates. */
  update(coarse: boolean) {
    const S = this.app.S;
    if (!S.section || S.pollutant === "O3") { this.data = null; this.draw(); return; }
    if (!S.sources.length) { this.data = { ...this.geometry(true), key: this.geomKey(true), units: new Map(), coarse: false }; this.draw(); return; }
    const key = this.geomKey(coarse);
    if (this.data && (this.data.key === key || (!coarse && this.data.key === this.geomKey(false)))) { this.draw(); return; }
    if (this.inflight) { this.queued = coarse; this.draw(); return; }
    this.request(coarse);
  }

  private async request(coarse: boolean) {
    const app = this.app, S = app.S;
    const { nx, nz, zTop, xs, ys, zs } = this.geometry(coarse);
    const key = this.geomKey(coarse), my = ++this.seq;
    this.inflight = true;
    const t0 = performance.now();
    try {
      const srcs = [...S.sources];
      const vals = await app.fc.points(S.scenarioId, app.wd(), srcs.map((s) => ({ sourceId: s.sourceId, x: s.x, y: s.y })), xs, ys, zs);
      if (my === this.seq) {
        const units = new Map<number, Float64Array>();
        srcs.forEach((s, i) => units.set(s.tag, vals[i]));
        this.data = { key, nx, nz, zTop, zs, xs, ys, units, coarse };
        this.lastMs = performance.now() - t0;
        if (!coarse) app.perf.samples.push({ what: `section ${nx}x${nz}, ${srcs.length} sources`, ms: this.lastMs });
      }
    } catch (e) {
      console.warn(e);
    } finally {
      this.inflight = false;
      this.draw();
      if (this.queued !== null) { const q = this.queued; this.queued = null; this.update(q); }
      else if (coarse) this.update(false);
    }
  }

  private geometry(coarse: boolean) {
    const sec = this.app.S.section!;
    const nx = coarse ? 70 : 170, nz = coarse ? 50 : 110, zTop = sec.zTop;
    const n = nx * nz, xs = new Float64Array(n), ys = new Float64Array(n), zs = new Float64Array(n);
    for (let k = 0; k < nz; k++) {
      const z = ((k + 0.5) / nz) * zTop;
      for (let i = 0; i < nx; i++) {
        const t = (i + 0.5) / nx, o = k * nx + i;
        xs[o] = sec.a.x + t * (sec.b.x - sec.a.x); ys[o] = sec.a.y + t * (sec.b.y - sec.a.y); zs[o] = z;
      }
    }
    return { nx, nz, zTop, xs, ys, zs };
  }

  private vertRequested = new Set<string>();
  /** Forget failed road requests so the next draw asks again (Retry). */
  retryFailed() { this.vertRequested.clear(); }
  private requestVertical(k: string, t: number) {
    if (this.vertRequested.has(k)) return;
    this.vertRequested.add(k);
    const app = this.app;
    app.roadMaps.loadVertical(app.S.scenarioId, t, app.roadPol()!).then((m) => { if (m) setTimeout(() => this.draw(), 0); });
  }

  /** Road increment aloft from the vertical companion; null where not computed (above 500 m). */
  private roadAt(x: number, y: number, z: number): number | null {
    const app = this.app;
    if (!app.roadsActive()) return 0;
    let v = 0, any = false;
    for (const t of app.tiersOn()) {
      const k = RoadMaps.key(app.S.scenarioId, t, app.roadPol()!);
      const vm = app.roadMaps.vertReady.get(k);
      if (!vm) { this.requestVertical(k, t); continue; }
      const r = verticalValue(vm, x, y, z);
      if (r == null) return null;
      v += r * app.S.roads.trafficScale; any = true;
    }
    return any ? v : 0;
  }

  draw() {
    const app = this.app, S = app.S, c = this.ctx, W = this.W, H = this.H;
    c.clearRect(0, 0, W, H); c.fillStyle = "#fff"; c.fillRect(0, 0, W, H);
    const side = $("sectionSide");
    const sec = S.section;
    if (!sec) { $("sectionMeta").textContent = ""; side.innerHTML = `<p class="hint">Place a source to start a section line, or drag its ends on the map.</p>`; return; }
    const L = { l: 48, r: 10, t: 12, b: 28 }, PW = W - L.l - L.r, PH = H - L.t - L.b;
    const len = Math.hypot(sec.b.x - sec.a.x, sec.b.y - sec.a.y);
    $("sectionMeta").textContent = `A→B ${(len / 1000).toFixed(1)} km, heights 0–${sec.zTop >= 1000 ? (sec.zTop / 1000).toFixed(1) + " km" : sec.zTop + " m"}`;
    const br = rampBreaks(app.scaleLoUg(), -1), lo = Math.log10(br[0]), step = Math.log10(br[1]) - lo;
    const d = this.data;
    const notes: string[] = [];
    const labels: { text: string; x: number; y: number; align: "left" | "right" | "center"; colour: string; above: boolean }[] = [];
    let roadsShown = false, roadsCut = false, maxInc = 0, aboveZi = 0;
    this.shown = null;
    const scn = app.scenario(), zi = scn.zi_effective_m;
    if (d && S.pollutant !== "O3") {
      const ek = app.emitKey();
      const q = S.sources.map((s) => ({ u: d.units.get(s.tag), q: app.effRate(s, ek), stack: app.kind(s) === "stack" }));
      const cw = PW / d.nx, ch = PH / d.nz;
      const inc = new Float64Array(d.nx * d.nz);
      for (let k = 0; k < d.nx * d.nz; k++) {
        let v = 0;
        for (const it of q) if (it.u && it.q) v += it.q * it.u[k];
        if (d.zs[k] > zi + 25) aboveZi = Math.max(aboveZi, stackAbove(q, k));
        if (app.roadsActive() && app.roadMaps.verticalAvailable) {
          const r = this.roadAt(d.xs[k], d.ys[k], d.zs[k]);
          if (r == null) roadsCut = true; else if (r > 0) { v += r; roadsShown = true; }
        }
        inc[k] = v; if (v > maxInc) maxInc = v;
      }
      this.shown = { inc, nx: d.nx, nz: d.nz, zTop: d.zTop, l: L.l, t: L.t, pw: PW, ph: PH, len: Math.hypot(sec.b.x - sec.a.x, sec.b.y - sec.a.y) };
      // Plume values upwind of a source lying on the line (AERMOD's meander component) get a note.
      for (const s of S.sources) {
        const t = ((s.x - sec.a.x) * (sec.b.x - sec.a.x) + (s.y - sec.a.y) * (sec.b.y - sec.a.y)) / (this.shown.len * this.shown.len);
        const off = Math.hypot(s.x - (sec.a.x + t * (sec.b.x - sec.a.x)), s.y - (sec.a.y + t * (sec.b.y - sec.a.y)));
        const iUp = Math.floor((t - 300 / this.shown.len) * d.nx);
        if (t < 0 || t > 1 || off > 250 || iUp < 1 || notes.includes("upwind")) continue;
        let up = false;
        for (let k = 0; k < d.nz && !up; k++) for (let i = 0; i < iUp; i++) if (inc[k * d.nx + i] >= br[0]) { up = true; break; }
        if (up) notes.push("upwind");
      }
      for (let k = 0; k < d.nz; k++) for (let i = 0; i < d.nx; i++) {
        const v = inc[k * d.nx + i];
        if (!(v >= br[0])) continue;
        const ci = Math.min(RAMP.length - 1, Math.floor((Math.log10(v) - lo) / step + 1e-9));
        c.fillStyle = RAMP[ci];
        c.fillRect(L.l + i * cw, L.t + PH - (k + 1) * ch, cw + 0.6, ch + 0.6);
      }
    }
    // axes
    c.strokeStyle = "#888"; c.lineWidth = 1; c.strokeRect(L.l, L.t, PW, PH);
    c.fillStyle = "#333"; c.font = "10.5px system-ui"; c.textAlign = "right"; c.textBaseline = "middle";
    const zt = sec.zTop > 1000 ? [0, 500, 1000, 1500, 2000, 2500] : [0, 100, 200, 300, 400, 500, 600];
    for (const z of zt) {
      const yy = L.t + PH - (z / sec.zTop) * PH;
      c.fillText(z >= 1000 ? z / 1000 + " km" : z + " m", L.l - 4, yy);
      c.strokeStyle = "rgba(0,0,0,.07)"; c.beginPath(); c.moveTo(L.l, yy); c.lineTo(L.l + PW, yy); c.stroke();
    }
    c.textAlign = "center"; c.textBaseline = "top";
    const kmStep = [1, 2, 5, 10].find((s) => (len / 1000 / s) * 46 <= PW) || 10;
    for (let dd = 0; dd <= len / 1000 + 1e-9; dd += kmStep) c.fillText(dd + " km", L.l + (dd * 1000 / len) * PW, L.t + PH + 4);
    c.font = "bold 11px system-ui"; c.fillText("A", L.l, L.t + PH + 15); c.fillText("B", L.l + PW, L.t + PH + 15);
    // zi line
    if (zi <= sec.zTop) {
      const yy = L.t + PH - (zi / sec.zTop) * PH;
      c.setLineDash([6, 4]); c.strokeStyle = "#a3001c"; c.lineWidth = 1.5; c.beginPath(); c.moveTo(L.l, yy); c.lineTo(L.l + PW, yy); c.stroke(); c.setLineDash([]);
      const txt = `zi = ${Math.round(zi)} m${scn.urbanApplies && Math.round(zi) !== Math.round(scn.zi_m) ? ` (urban layer; AERMET zi ${Math.round(scn.zi_m)} m)` : ""}`;
      labels.push({ text: txt, x: L.l + PW - 4, y: yy, align: "right", colour: "#a3001c", above: yy - L.t > 20 });
      // "zi" tag in the axis margin, beside the line
      c.fillStyle = "#a3001c"; c.font = "bold 10px system-ui"; c.textAlign = "left"; c.textBaseline = "middle"; c.fillText("zi", 3, yy);
      if (S.sources.length) notes.push("zi_step");
    } else {
      labels.push({ text: zi > 2500 ? `zi = ${Math.round(zi)} m (above the top of the stored fields, 2.5 km)` : `zi = ${Math.round(zi)} m (above this view)`, x: L.l + PW - 4, y: L.t + 2, align: "right", colour: "#a3001c", above: false });
    }
    // roads computed to 500 m
    if (roadsShown && roadsCut && 500 < sec.zTop) {
      const yy = L.t + PH - (500 / sec.zTop) * PH;
      c.setLineDash([2, 3]); c.strokeStyle = "#555"; c.lineWidth = 1; c.beginPath(); c.moveTo(L.l, yy); c.lineTo(L.l + PW, yy); c.stroke(); c.setLineDash([]);
      labels.push({ text: "roads computed to 500 m", x: L.l + 4, y: yy, align: "left", colour: "#333", above: true });
    }
    // near-stack hatch and stacks drawn to height
    for (const st of S.sources.filter((s) => app.kind(s) === "stack")) {
      const t = ((st.x - sec.a.x) * (sec.b.x - sec.a.x) + (st.y - sec.a.y) * (sec.b.y - sec.a.y)) / (len * len);
      const px = sec.a.x + t * (sec.b.x - sec.a.x), py = sec.a.y + t * (sec.b.y - sec.a.y), off = Math.hypot(st.x - px, st.y - py);
      if (t < 0 || t > 1 || off > 250) continue;
      const half = (Math.sqrt(250 * 250 - off * off) / len) * PW, xc = L.l + t * PW;
      c.save(); c.beginPath(); c.rect(xc - half, L.t, 2 * half, PH); c.clip();
      c.strokeStyle = "rgba(120,0,30,.45)"; c.lineWidth = 1;
      for (let k = -PH; k < 2 * half + PH; k += 5) { c.beginPath(); c.moveTo(xc - half + k, L.t); c.lineTo(xc - half + k - PH, L.t + PH); c.stroke(); }
      c.restore();
      const h = app.family(st.family).options.find((o) => o.id === st.sourceId)?.h ?? 0;
      c.fillStyle = "#222"; c.fillRect(xc - 1.5, L.t + PH - (h / sec.zTop) * PH, 3, (h / sec.zTop) * PH);
      labels.push({ text: `S${st.tag} · unresolved`, x: xc, y: L.t + 2, align: "center", colour: "#6b0014", above: false });
      if (!notes.includes("near_stack")) notes.push("near_stack");
    }
    // Labels last, each on a white box with a coloured edge so they read over the plume colours.
    c.font = "11px system-ui"; c.textBaseline = "middle";
    const placed: [number, number, number, number][] = [];
    for (const lb of labels) {
      const w = c.measureText(lb.text).width + 8, h = 16;
      let x0 = lb.align === "right" ? lb.x - w : lb.align === "center" ? lb.x - w / 2 : lb.x;
      x0 = Math.max(L.l + 1, Math.min(L.l + PW - w - 1, x0));
      let y0 = lb.above ? lb.y - h - 2 : lb.y + 2;
      // Step clear of labels already drawn (in the label's own direction).
      for (let k = 0; k < 6 && placed.some(([a, b, cw, ch]) => x0 < a + cw && a < x0 + w && y0 < b + ch && b < y0 + h); k++) y0 += lb.above ? -(h + 2) : h + 2;
      y0 = Math.max(L.t, Math.min(L.t + PH - h, y0));
      placed.push([x0, y0, w, h]);
      c.fillStyle = "rgba(255,255,255,.94)"; c.fillRect(x0, y0, w, h);
      c.strokeStyle = lb.colour; c.lineWidth = 1; c.strokeRect(x0 + 0.5, y0 + 0.5, w - 1, h - 1);
      c.fillStyle = lb.colour; c.textAlign = "left"; c.fillText(lb.text, x0 + 4, y0 + h / 2 + 0.5);
    }
    if (d && maxInc > 0 && aboveZi > 0.01 * maxInc && scn.L_m < 0 && zi <= 2500) notes.push("penetrated");
    if (d && aboveZi >= br[0] && scn.L_m > 0 && zi <= 2500) notes.push("above_zi_stable");   // stack plume visible above zi
    if (scn.urbanApplies && Math.round(zi) !== Math.round(scn.zi_m) && S.sources.length) notes.push("urban_zi");
    if (scn.id === "neutral_windy" && S.sources.some((s) => app.kind(s) !== "stack")) notes.push("neutral_ground");
    if (roadsShown) { notes.push("road_no_zi"); notes.push("roads_aloft"); }
    notes.push("steady");
    const roadsNote = app.roadsActive() && !app.roadMaps.verticalAvailable ? `<div class="flagline grey"><span>Road contributions aloft are not computed; the section shows placed sources only.</span></div>` : "";
    const noSrc = !S.sources.length ? `<p class="hint">No placed sources: the section shows ${app.roadsActive() && app.roadMaps.verticalAvailable ? "road plumes only" : "nothing yet"}.</p>` : "";
    side.innerHTML = `<div><b>Plume increment</b> (${LABEL[S.pollutant]}, no background)</div>
      <div class="ramp" aria-hidden="true">${RAMP.map((col) => `<span style="background:${col}"></span>`).join("")}</div>
      <div class="hint" style="display:flex;justify-content:space-between"><span>${esc(app.showC(br[0]))}</span><span>${esc(app.showC(br[0] * 1000))}</span></div>
      ${noSrc}${roadsNote}
      ${S.pollutant === "O3" ? `<div class="flagline red"><span>No ozone fields: see the Linearity edge module.</span></div>` : ""}
      <div><b>Model notes on this section</b></div>
      ${notes.map((n) => `<div class="lim-item"><button class="i-mark" data-lim="${n}" aria-label="About: ${esc(LIMITS[n].title)}">i</button><span>${esc(LIMITS[n].title)}</span></div>`).join("")}
      ${d?.coarse ? `<p class="hint">Coarse preview while dragging.</p>` : ""}`;
    app.panels.bindLimits(side);
    this.cv.setAttribute("aria-label", `Vertical cross-section along A to B, ${(len / 1000).toFixed(1)} km long; highest plume increment ${app.showC(maxInc)}.`);
  }
}

// Part of the increment from stacks above zi (for the penetrated-plume note).
function stackAbove(q: { u?: Float64Array; q: number; stack: boolean }[], k: number): number {
  let v = 0;
  for (const it of q) if (it.stack && it.u && it.q) v += it.q * it.u[k];
  return v;
}
