// Types for export/fields/manifest.json (format aqsim-fields v2). No DOM access.
import type { ScenarioMeta } from "../types";

export interface GridSpec {
  dims: string[];
  shape: [number, number, number];
  z_m: number[];
  r_m?: number[];
  phi_deg?: number[];
  s_m?: number[];
  d_m?: number[];
  level_bytes?: number;
  order?: string;
}

export interface FieldEntry {
  source_id: string;
  scenario_id: string;
  frame: "polar" | "road";
  orientation_deg: number | null;
  file: string;
  bytes: number;
  gzip_bytes?: number;
  sha256?: string;
  max: number;
  ground_max: number;
  ground_max_at: { r?: number; phi?: number; s?: number; d?: number };
  wd_deg: number;
  zi_m: number;
  L_m: number;
  checks?: { idx: [number, number, number]; code?: number; value: number }[];
  provenance?: Record<string, unknown>;
  log10_min: number;
  log10_step: number;
  scale?: number;
}

export interface SourceMeta {
  id: string;
  label: string;
  category: string;
  aermod_type: string;
  params: Record<string, number>;
  orientation_deg?: number;
  family?: string;
  control?: string;
  [k: string]: unknown;
}

/** Road-baseline entry (C, Phase 3): one ground map per scenario x tier x pollutant. */
export interface RoadBaselineEntry {
  scenario_id: string;
  tier: number;
  pollutant: string;            // "NOx" | "CO" | "PM25"
  file: string;
  log10_min: number;
  log10_step: number;
  max?: number;
  z_file?: string | null;       // optional vertical companion
  [k: string]: unknown;
}

export interface RoadBaselineBlock {
  grid?: { nx: number; ny: number; x0?: number; y0?: number; xmin?: number; ymin?: number; d?: number; resolution_m?: number; order?: string; [k: string]: unknown };
  encoding?: { name: string; [k: string]: unknown };
  z_m?: number[];
  entries?: RoadBaselineEntry[];
  maps?: RoadBaselineEntry[];
  [k: string]: unknown;
}

export interface Manifest {
  format: string;
  format_version: number;
  created?: string;
  units: string;
  frames: Record<string, unknown>;
  grids: Record<string, GridSpec>;
  encoding: { name: string; [k: string]: unknown };
  interpolation: Record<string, unknown>;
  sources: Record<string, SourceMeta>;
  scenarios: Record<string, ScenarioMeta>;
  fields: FieldEntry[];
  totals?: { n_fields: number; bytes: number; gzip_bytes: number };
  road_baselines?: RoadBaselineBlock;
  [k: string]: unknown;
}

export function fieldEntry(m: Manifest, sourceId: string, scenarioId: string): FieldEntry | undefined {
  return m.fields.find((f) => f.source_id === sourceId && f.scenario_id === scenarioId);
}

/** URL of a data file, tagged with its content hash when the manifest has one, so a browser never
 *  decodes a cached tile from an older export with a newer manifest's scale. */
export function dataFileUrl(base: string, file: string, sha256?: string): string {
  return base + "fields/" + file + (sha256 ? "?v=" + sha256.slice(0, 12) : "");
}
